(224, 358, '93', '178', 'ابيض', 'متوسط البنية', 'بصحه جيده والحمد لله', 'متدين كثيرا', 'اصلي دائما', 'غير مدخن', 'ملتحي', NULL, 'دراسة جامعية', 'متوسط', 'لا زلت ادرس', 'معماري وتاجر', 'اقل من 500', 'من النارد جدا أن تجد امرأةً تصلي بخشوع، معرضة عن اللغو، تزكي إذا كانت تجب عليها الزكاة، حافظة لفرجها، راعية لأماناتها وعهدها، محافظة على صلاتها.... في الحقيقة هذه متطلبات الدخول للفردوس كما قال الله في أول سورة المؤمنون، وهي مواصفات الزوجة التي ابحث عنها.', 'الناس مؤتمنون على أنسابهم، وأنا من نسب الرسول صلى الله عليه وسلم. لقب عائلتي الحسيني -فنحن من نسب الحسين رضي الله عنه- ولكن جدي غيرها لسم بسبب كرامة قيل انها حصلت له، حيث حاول أناس وهو في تركيا قتله بطعام فيه سم، فسمى بالله وأكل ولم يمت. عموما، للاسف لا اجد من يطبق هذه الآية: ﴿وأنكحوا الأيامى منكم والصالحين من عبادكم وإمائكم إن يكونوا فقراء يغنهم الله من فضله والله واسع عليم﴾ [النور: ٣٢]... فأنا عندي كل ما تتمناه المرأة المتدينة في الشاب إلا المال حاليا. صورتي الشخصية لي وانا صغير.', '2024-08-15 19:02:03', '2024-08-15 19:02:03'),
(225, 359, '70', '165', 'حنطي مائل للبياض', 'متوسط البنية', 'بصحه جيده والحمد لله', 'افضل ان لا اقول', 'اصلي دائما', 'غير مدخنة', NULL, 'محجبة (النقاب)', 'دراسة جامعية', 'قريب من المتوسط', 'لا زلت ادرس', 'طالبة', 'بدون دخل شهري', 'شخص خلوق شخصيته جيدة يخاف ربه فيني', 'فتاة متوسطة الجمال مثقفة ولدي الجدية ف الارتباط', '2024-08-16 00:15:24', '2024-08-16 00:15:24'),
(226, 360, '93', '178', 'ابيض', 'متوسط البنية', 'بصحه جيده والحمد لله', 'متدين كثيرا', 'اصلي دائما', 'غير مدخن', 'ملتحي', NULL, 'دراسة جامعية', 'اكتر من المتوسط', 'لا زلت ادرس', 'معماري وتاجر ومسوق', 'اقل من 500', 'من النارد جدا أن تجد امرأةً تصلي بخشوع، معرضة عن اللغو، تزكي إذا كانت تجب عليها الزكاة، حافظة لفرجها، راعية لأماناتها وعهدها، محافظة على صلاتها.... في الحقيقة هذه متطلبات الدخول للفردوس كما قال الله في أول سورة المؤمنون، وهي مواصفات الزوجة التي ابحث عنها.', 'يقال عني بأني متدين جدا، حسن الخلق، هادئ الطبع، ويقال أننا من نسب الحسين رضي الله عنه، أبحث عن زوجة متدينة لأخبطتها إن شاء الله، لا لأتزوجها، فأنا ما زلت أحتاج لبعض الوقت لجمع المال، ربما إذا خطبت تزداد همتي لذلك أكثر وأكثر، فأنا عندي المهارة اللازمة للعمل كمهندس معماري بفضل الله', '2024-08-16 06:32:31', '2024-08-27 17:00:41'),
