(292, 430, '94', '171', 'ابيض', 'متوسط البنية', 'بصحه جيده والحمد لله', 'متدينة قليل', 'اصلي دائما', 'غير مدخنة', NULL, 'محجبة (النقاب)', 'دراسة ثانوية', 'متوسط', 'بدون عمل حاليا', 'لايوجد', 'بين 500 دولار و 1000 دولار', 'اتمنى اجد من شروره طيب كفو واخلاقه عاليه موظف رجل شرقي غيور غيره لايدخل يتبع', 'غير متحرره ولا ملتزمه عاديه لكن طبعي عربي اصيل ابحث عن العفاف والحنان في كنف رجل حنون شرقي عربي يتبع', '2024-09-16 11:29:19', '2024-09-16 11:29:19'),
